package com.texuli.conformance

import com.texuli.emojis.EmojiEngine
import com.texuli.spec.JsonValue
import com.texuli.spec.runtime.parseJson
import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull

/** Shared cases are generated by the web engine; every index is a UTF-16 code-unit offset. */
class EmojiConformanceTest {
    private val repo = File(System.getProperty("texuli.repo") ?: error("texuli.repo is not set"))
    private val fixture = File(repo, "tests/fixtures/emojis/conformance.json")

    private fun obj(value: JsonValue?): Map<String, JsonValue> =
        (value as? JsonValue.Obj)?.fields ?: error("expected object, got $value")
    private fun str(value: JsonValue?): String =
        (value as? JsonValue.Str)?.value ?: error("expected string, got $value")
        private fun matchJson(match: com.texuli.emojis.EmojiMatch): JsonValue = JsonValue.Obj(linkedMapOf(
        "id" to JsonValue.Str(match.id),
        "unicode" to JsonValue.Str(match.unicode),
        "start" to JsonValue.Num(match.start.toDouble()),
        "end" to JsonValue.Num(match.end.toDouble()),
        "kind" to JsonValue.Str(match.kind),
        "source" to JsonValue.Str(match.source),
    ))

    private fun tokenJson(token: com.texuli.emojis.EmojiToken): JsonValue = when (token) {
        is com.texuli.emojis.EmojiToken.Text -> JsonValue.Obj(linkedMapOf(
            "type" to JsonValue.Str("text"), "text" to JsonValue.Str(token.text),
            "start" to JsonValue.Num(token.start.toDouble()), "end" to JsonValue.Num(token.end.toDouble()),
        ))
        is com.texuli.emojis.EmojiToken.Emoji -> {
            val match = obj(matchJson(token.match))
            JsonValue.Obj(linkedMapOf("type" to JsonValue.Str("emoji")) + match)
        }
    }

    @Test
    fun generatedCatalogLookupAndWebFixturesAgree() {
        val root = obj(parseJson(fixture.readText()))
        assertEquals("texuli-emoji-conformance/v1", str(root["schemaVersion"]))
        assertEquals("UTF-16 code units", str(root["offsetUnit"]))
        val cases = (root["cases"] as JsonValue.Arr).items
        var casesChecked = 0
        var matchesChecked = 0
        for (value in cases) {
            val case = obj(value)
            val input = str(case["input"])
            val expectedMatches = case["matches"] as JsonValue.Arr
            val actualMatches = EmojiEngine.findEmojis(input)
            assertEquals(expectedMatches, JsonValue.Arr(actualMatches.map(::matchJson)), str(case["name"]))
            assertEquals(case["tokens"], JsonValue.Arr(EmojiEngine.parseEmojiTokens(input).map(::tokenJson)), str(case["name"]))
            assertEquals(str(case["toUnicode"]), EmojiEngine.toUnicode(input), str(case["name"]))
            assertEquals(str(case["toShortcodes"]), EmojiEngine.toShortcodes(input), str(case["name"]))
            casesChecked++
            matchesChecked += actualMatches.size
        }
        assertEquals(12, casesChecked)
        assertEquals(11, matchesChecked)
    }

    @Test
    fun generatedCatalogResolvesOnlyCanonicalEntries() {
        assertEquals(3963, EmojiEngine.catalogSize)
        assertNotNull(EmojiEngine.getEmoji(":thumbs_up:"))
        assertNotNull(EmojiEngine.getEmoji("  1f44d  "))
        assertNotNull(EmojiEngine.getEmoji("\uD83D\uDC4D"))
        assertEquals(null, EmojiEngine.getEmoji(":thumbsup:"))
        assertEquals(null, EmojiEngine.getEmoji("x".repeat(257)))
    }
}
